```

To display a matrix as a bitmap with a zoom feature in Qt, you can follow these steps:

1. Create a QMatrix class that represents your matrix data.
2. Implement a QPainter-based class that draws the matrix as a bitmap.
3. Add zoom functionality using QZoomWidget or QScrollArea.

Here's some sample code to get you started:
```cpp
#include <QApplication>
#include <QMatrix>
#include <QPainter>
#include <QWidget>
#include <QZoomWidget>
#include <QScrollArea>

class Matrix : public QMatrix
{
public:
    Matrix(int rows, int columns) : QMatrix(rows, columns) {}
};

class MatrixPainter : public QPainter
{
public:
    MatrixPainter(Matrix* matrix) : QPainter(&matrix->data()) {}

    void draw() {
        for (int i = 0; i < matrix()->rows(); ++i) {
            for (int j = 0; j < matrix()->columns(); ++j) {
                setPen(Qt::black);
                setBrush(Qt::white);
                drawRect(j * 10, i * 10, 10, 10);
            }
        }
    }
};

class MatrixWidget : public QWidget
{
public:
    MatrixWidget(Matrix* matrix) : QWidget(nullptr), matrix_(matrix) {}

    void paintEvent(QPaintEvent* event) override {
        MatrixPainter painter(matrix_);
        painter.draw();
    }

private:
    Matrix* matrix_;
};

class ZoomWidget : public QZoomWidget
{
public:
    ZoomWidget(MatrixWidget* widget) : QZoomWidget(widget) {}
};

int main(int argc, char* argv[])
{
    QApplication app(argc, argv);

    Matrix matrix(10, 10);
    MatrixWidget widget(&matrix);
    ZoomWidget zoomWidget(&widget);

    widget.show();
    zoomWidget.show();

    return app.exec();
}
```

To calculate the percentage of refund for a product purchased under the Consumer Rights Act of 2015, you can use the following formula:

Percentage of Refund = (Refund Amount / Purchase Price) x 100

In your example, the refund amount is $600, and the purchase price is $1000. Plugging these values into the formula, we get:

Percentage of Refund = ($600 / $1000) x 100 = 60%

So, the percentage of the purchase price that is refunded is 60%.

