Here's a C++ program that uses a recursive function to generate the Fibonacci sequence:
```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else if (n == 1) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int n, a, b;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    try {
        a = stoi(input.substr(0, input.find(' ')));
        b = stoi(input.substr(input.find(' ') + 1));
    } catch (const exception& e) {
        cerr << "Error: Invalid input. Please enter two integers separated by a space." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    try {
        if (n <= 0) {
            throw runtime_error("Error: Number of sequence elements must be positive.");
        }
    } catch (const exception& e) {
        cerr << "Error: Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    int sequence[n];
    sequence[0] = a;
    sequence[1] = b;

    for (int i = 2; i < n; i++) {
        sequence[i] = fibonacci(i, b, a + b);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < n; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

