import React, { useState } from 'react';
import { View, Text, ScrollView } from 'react-native';

const CustomScrollView = ({ children }) => {
  const [focusedSection, setFocusedSection] = useState(0);
  const [scrollPosition, setScrollPosition] = useState(0);

  const handleScroll = (event) => {
    setScrollPosition(event.nativeEvent.contentOffset.y);

    // Prevent scrolling to uncofused sections
    if (event.nativeEvent.contentOffset.y > focusedSection * 100 && event.nativeEvent.contentOffset.y < (focusedSection + 1) * 100) {
      event.preventDefault();
      setScrollPosition(focusedSection * 100);
    }
