    video1.name = "Video 1";

    // Import the second video file
    var video2 = comp.layers.add(videoFile2);
    video2.name = "Video 2";

    // Stack the videos vertically
    var stackedVideos = [video1, video2];
    for (var i = 1; i < stackedVideos.length; i++) {
        stackedVideos[i].transform.position.y = stackedVideos[i - 1].bounds.height;
    }

    // Add subtitles to the top half of the video
    var subtitleLayer = comp.layers.addText(textFile.contents, "Subtitles");
    subtitleLayer.name = "Subtitles";
    subtitleLayer.transform.position.y = video1.bounds.height / 2;

    // Set the subtitle layer's font and size
    subtitleLayer.font = "Arial";
    subtitleLayer.size = 24;

    // Render the composition
    comp.render();
}

main();
