    ['name' => 'Jane', 'address' => '456 Elm St', 'age' => 25],
    ['name' => 'Bob', 'address' => '789 Oak St', 'age' => 35]
];

$sorted_set = smart_sort_array($set, 'asc'); // Sort in ascending order
$sorted_set = smart_sort_array($set, 'desc'); // Sort in descending order

print_r($sorted_set);
