Here's a simple C program that takes command-line arguments and converts them into a single string:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *input = malloc(sizeof(char) * (argc + 1));

    for (int i = 0; i < argc; i++) {
        strcat(input, argv[i]);
        if (i != argc - 1) {
            strcat(input, " ");
        }
    }

    printf("Input string: %s\n", input);

    free(input);

    return 0;
}
```

