To create a simple toast notification using React context, follow these steps:

1. Create a `ToastContext` file:

```javascript
import React, { createContext, useContext } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = React.useState(null);

  function showToast(message) {
    setToast(message);
    setTimeout(() => {
      setToast(null);
    }, 3000);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. In your main application file, import the `ToastContext` and wrap your app in the `ToastProvider`:

```javascript
import React from 'react';
import ReactDOM from 'react-dom';
import ToastContext from './ToastContext';
import App from './App';

ReactDOM.render(
  <ToastContext.Provider value={{ showToast: () => {} }}>
    <App />
  </ToastContext.Provider>,
  document.getElementById('root')
);
```

3. In your component where you want to display the toast notification, import the `ToastContext` and use the `showToast` function:

```javascript
import React, { useContext } from 'react';
import { ToastContext } from './ToastContext';

function MyComponent() {
  const { showToast } = useContext(ToastContext);

  function handleClick() {
    showToast('This is a toast notification!');
  }

  return (
    <div onClick={handleClick}>
      Click me to show a toast notification!
    </div>
  );
}

export default MyComponent;
```

Now, when you click on the button in the `MyComponent`, a toast notification will be displayed at the top of the screen for 3 seconds.

