Here are four methods to open and close the camera and microphone in JavaScript:

Method 1: Using getUserMedia() and StreamTrack API

```javascript
function openCamera() {
  const constraints = {
    video: true,
    audio: false
  };

  navigator.mediaDevices.getUserMedia(constraints)
    .then(stream => {
      const videoElement = document.createElement('video');
      videoElement.srcObject = stream;
      videoElement.play();
    })
    .catch(error => console.error('Error opening camera:', error));
}

function closeCamera() {
  const videoElement = document.querySelector('video');
  if (videoElement) {
    videoElement.srcObject.getTracks().forEach(track => track.stop());
    videoElement.srcObject = null;
  }
}

function openMicrophone() {
  const constraints = {
    video: false,
    audio: true
  };

  navigator.mediaDevices.getUserMedia(constraints)
    .then(stream => {
      const audioElement = document.createElement('audio');
      audioElement.srcObject = stream;
      audioElement.play();
    })
    .catch(error => console.error('Error opening microphone:', error));
}

function closeMicrophone() {
  const audioElement = document.querySelector('audio');
  if (audioElement) {
    audioElement.srcObject.getTracks().forEach(track => track.stop());
    audioElement.srcObject = null;
  }
}
```

Method 2: Using MediaStreamRecorder API

```javascript
function openCameraAndRecord() {
  const constraints = {
    video: true,
    audio: true
  };

  navigator.mediaDevices.getUserMedia(constraints)
    .then(stream => {
      const mediaStreamRecorder = new MediaStreamRecorder(stream);
      mediaStreamRecorder.start();

      // Record for a specific duration or until the stop button is clicked
      setTimeout(() => {
        mediaStreamRecorder.stop();
      }, 3000);

