Here's a simple React utility to remove widows. This component will check if the text inside it has any words that are wider than the container, and if so, it will adjust the font size to fit the content without creating widows.

```jsx
import React, { useRef, useState } from 'react';

const WidowRemover = ({ children }) => {
  const textRef = useRef(null);
  const [fontSize, setFontSize] = useState(16);

  const handleResize = () => {
    const textWidth = textRef.current.offsetWidth;
    const fontSizeValue = parseFloat(getComputedStyle(textRef.current).fontSize);
    const wordSpacing = parseFloat(getComputedStyle(textRef.current).wordSpacing);

    const words = textRef.current.textContent.split(' ');
    const lineHeight = fontSizeValue * 1.2; // Adjust the line height as needed

    let maxWidth = textWidth - wordSpacing;

    for (let i = 0; i < words.length; i++) {
      const wordWidth = words[i].offsetWidth;

      if (wordWidth > maxWidth) {
        maxWidth = wordWidth;
      }
    }

    const newFontSize = Math.max(fontSizeValue, maxWidth / lineHeight);

    setFontSize(newFontSize);
  };

  return (
    <div ref={textRef} style={{ fontSize }} onResize={handleResize}>
      {children}
    </div>
  );
};

export default WidowRemover;
```

